WITH counts AS (SELECT sm.id,count(*) FILTER (WHERE length(trim(coalesce(e.value->>'why','')))<25) short_count FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) e(value) WHERE sm.content_status='active' AND sm.practice_review ? 'explanation_quality_audit' GROUP BY sm.id), updated AS (SELECT sm.id,jsonb_set(sm.practice_review,'{explanation_quality_audit}',(sm.practice_review->'explanation_quality_audit') || jsonb_build_object('short_explanation_count',c.short_count,'status',CASE WHEN c.short_count=0 THEN 'short_explanations_resolved_pending_substantive_review' ELSE 'needs_substantive_review' END,'rechecked_at','2026-11-21'),true) review FROM study_materials sm JOIN counts c ON c.id=sm.id) UPDATE study_materials sm SET practice_review=u.review,updated_at=now() FROM updated u WHERE sm.id=u.id AND sm.practice_review IS DISTINCT FROM u.review;